//! Recusas e falhas inesperadas concluem o estado e soltam a posse sem reiniciar.
#![cfg(unix)]
use hangar_server::update::git_engine::{Service,releases::{Source,DownloadError}};
use serde_json::Value;
use std::{os::unix::fs::PermissionsExt,io::{Read,Write},sync::{Arc,atomic::{AtomicBool,Ordering}}};
use super::update_local_dist::git;
struct Unused;impl Source for Unused{fn get(&self,_:&str,_:std::time::Duration)->Result<Vec<u8>,DownloadError>{panic!("não consulta release");}}
#[test]
fn update_pipeline_errors_keep_cause_release_owner_and_skip_restart(){
 let fixture:Value=serde_json::from_str(include_str!("../../../../backend/tests/fixtures/contract/update-git/pipeline-errors.json")).unwrap();let mut differences=vec![];let listener=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let port=listener.local_addr().unwrap().port();listener.set_nonblocking(true).unwrap();let stop=Arc::new(AtomicBool::new(false));let done=stop.clone();let server=std::thread::spawn(move||{while !done.load(Ordering::SeqCst){if let Ok((mut stream,_))=listener.accept(){stream.set_nonblocking(false).unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(2))).unwrap();let mut buffer=[0;4096];let _=stream.read(&mut buffer);let _=stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok");}else{std::thread::sleep(std::time::Duration::from_millis(2));}}});
 for row in fixture["cases"].as_array().unwrap(){let name=row["name"].as_str().unwrap();let temp=tempfile::tempdir().unwrap();let root=temp.path().join("repo");let origin=temp.path().join("origin");let bin=temp.path().join("bin");let calls=temp.path().join("calls");std::fs::create_dir(&root).unwrap();std::fs::create_dir(&bin).unwrap();std::fs::write(root.join("content"),"old").unwrap();git(&root,&["init","-b","main"]);git(&root,&["add","."]);git(&root,&["commit","-m","fixture"]);git(temp.path(),&["clone","--bare",root.to_str().unwrap(),origin.to_str().unwrap()]);git(&root,&["remote","add","origin",origin.to_str().unwrap()]);git(&root,&["fetch","origin"]);git(&root,&["branch","--set-upstream-to=origin/main"]);let head=git(&root,&["rev-parse","HEAD"]);let advanced=name=="unexpected-after-code";if advanced{std::fs::write(root.join("new.txt"),"new").unwrap();git(&root,&["add","."]);git(&root,&["commit","-m","new"]);git(&root,&["push","origin","main"]);git(&root,&["reset","--hard",&head]);}
  for program in ["uv","node","npm","tmux","systemctl","launchctl"]{let path=bin.join(program);std::fs::write(&path,if matches!(program,"systemctl"|"launchctl"){"#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"$CALLS\"\nexit 0\n"}else{"#!/bin/sh\nexit 0\n"}).unwrap();std::fs::set_permissions(path,std::fs::Permissions::from_mode(0o755)).unwrap();}
  let home=temp.path().join("home");let service=Service::new(home.clone(),root.clone(),temp.path().join("claude"),[("HOME".into(),home.display().to_string()),("PATH".into(),format!("{}:/usr/bin:/bin",bin.display())),("CALLS".into(),calls.display().to_string()),("CP_RUST_SERVER".into(),"0".into()),("CP_UPDATE_BRANCH".into(),"".into()),("GIT_CONFIG_GLOBAL".into(),"/dev/null".into()),("GIT_CONFIG_NOSYSTEM".into(),"1".into())].into());service.take_turn().unwrap().unwrap().transferred();
  let expected=&row["calls"].as_array().unwrap().iter().find(|call|call["method"]=="executar").unwrap()["result"];let cause=expected["erro"].as_str().unwrap();let state=service.execute_with_preparer(port,&Unused,None,&|_,_,dist,_,_,_|{if !dist{return Ok(());}if name.contains("inesperado")||advanced{std::panic::panic_any(cause.to_owned());}Err(cause.into())});
  for key in ["fase","ok","erro","voltou"]{if state.get(key).unwrap_or(&Value::Null)!=&expected[key]{differences.push(format!("{name}: {key}: {:?} != {}",state.get(key),expected[key]));}}
  assert!(!service.state_dir.join("rodando.lock").exists(),"{name}: posse órfã");assert_eq!(git(&root,&["rev-parse","HEAD"]),head);assert_eq!(std::fs::read_to_string(calls).unwrap_or_default().lines().filter(|line|*line==if cfg!(target_os="macos"){"kickstart"}else{"restart"}).count(),usize::from(advanced),"{name}: reinício/compensação");
 }
 stop.store(true,Ordering::SeqCst);server.join().unwrap();assert!(differences.is_empty(),"{}",differences.join("\n"));
}
